import React, { Component } from 'react'
import { YearPicker, MonthPicker, DayPicker } from 'react-dropdown-date'
import PropTypes from 'prop-types'
import DateWrapper from './index.style'
import moment from 'moment'

let date = {}

class DatePicker extends Component {
  constructor (props) {
    super(props)
    this.state = { year: null, month: null, day: null }
  }
  componentDidMount = () => {
  }

  onChangeDate = params => {
    date = { ...date, ...params }
    let mergeDate = ''
    if (date.hasOwnProperty('day') && date.hasOwnProperty('month') && date.hasOwnProperty('year')) {
      mergeDate = new Date(date.year, date.month, date.day)
      const spt = moment(mergeDate)
      this.props.selectedDate(spt)
    }
  }

  render () {
    return (
      <DateWrapper>
        <DayPicker
          defaultValue={'DD'}
          // mandatory
          year={this.state.year}
          // mandatory
          month={this.state.month}
          // mandatory if end={} is given in YearPicker
          endYearGiven
          // default is false
          required
          // default is false
          disabled={false}
          // mandatory
          onChange={day => this.onChangeDate({ day: day })}
          id={'day'}
          name={'day'}
          classes={'day-picker'}
          optionClasses={'option classes'}
        />
        <MonthPicker
          defaultValue={'MM'}
          // to get months as numbers
          numeric
          // default is full name
          short
          // default is Titlecase
          caps
          // mandatory if end={} is given in YearPicker
          endYearGiven
          // mandatory
          year={this.state.year}
          // default is false
          required
          // default is false
          disabled={false}
          // mandatory
          onChange={month => this.onChangeDate({ month: month })}
          id={'month'}
          name={'month'}
          classes={'month-picker'}
          optionClasses={'option classes'}
        />
        <YearPicker
          defaultValue={'YYYY'}
          // default is 1900
          start={this.props.minYear}
          // default is current year
          end={this.props.maxYear}
          // default is ASCENDING
          reverse
          // default is false
          required
          // default is false
          disabled={false}
          // mandatory
          onChange={year => this.onChangeDate({ year: year })}
          id={'year'}
          name={'year'}
          classes={'year-picker'}
          optionClasses={'option classes'}
        />
      </DateWrapper>

    )
  }
}

DatePicker.propTypes = {
  maxYear: PropTypes.number,
  minYear: PropTypes.number,
  selectedDate: PropTypes.func.isRequired
}

DatePicker.defaultProps = {
  maxYear: undefined,
  minYear: undefined,
  selectedDate: (value) => console.log(value)
}

export default DatePicker
