import React, { Component } from 'react'
import { connect } from 'react-redux'
import { notification } from 'antd'

import CtHealthWrapper from './index.style'
import appActions from '../../../redux/app/actions'
import querySearchBuilder from '../../../helpers/querySearchBuilder'
import DatePicker from '../../Datepicker'
import moment from 'moment'

const { showOverlay, resetOverlay } = appActions

const MEMBER_CONFIG = {
  self: {
    minYear: 18,
    maxYear: 59
  },
  spouse: {
    minYear: 21,
    maxYear: 60
  },
  child: {
    minYear: 0.5,
    maxYear: 60
  }
}

// RELATIONSHIP MAP
// 1: Self
// 2: Spouse
// 3-5: Child

class CtHealth extends Component {
  constructor (props) {
    super(props)
    this.state = {
      selectedMembers: ['self'],
      memberInfo: {
        self: null,
        spouse: null
      },
      childrenInfo: {
        child_1: null
      },
      errors: {}
    }
  }
  componentDidMount = () => {
    const searchParams = new URLSearchParams(this.props.location.search)
    // const coupon = searchParams.get('coupon') // will be added after release
    const utmMedium = searchParams.get('utm_medium')
    const utmSource = searchParams.get('utm_source')
    const utmCampaign = searchParams.get('utm_campaign')

    // will be added after release
    // if (coupon && ['GET25OFF', 'GET25%OFF'].includes(coupon)) {
    //   const overlay = (
    //     <CrackscreenPromoOverlay>
    //       <img
    //         className='promo-overlay'
    //         onClick={() => this.props.resetOverlay()}
    //       />
    //     </CrackscreenPromoOverlay>
    //   )

    //   this.props.showOverlay(overlay)
    //   this.setState({
    //     coupon
    //   })
    // }

    this.setState({
      utmMedium,
      utmSource,
      utmCampaign
    })
  }

  errorNotification = (message = 'Terjadi kesalahan') => {
    notification.error({
      message
    })
  }

  validateMemberAge (key, value) {
    const requiredAge = MEMBER_CONFIG[key] || MEMBER_CONFIG['child']
    const { minYear, maxYear } = requiredAge

    let errorStr = ''
    if (!value) {
      errorStr = 'Wajib diisi'
    } else {
      const age = moment().diff(value, 'years', true)
      if (age < minYear) {
        errorStr = `Umur kurang dari ${minYear} tahun`
      } else if (age > maxYear) {
        errorStr = `Umur lebih dari ${maxYear} tahun`
      }
    }

    return errorStr
  }

  resetErrors = () => {
    this.setState({ errors: {} })
  }

  validateObj = (inputObj, cb) => {
    // check each object's value
    const errorObj = Object.keys(inputObj).reduce((obj, key) => {
      obj[key] = this.validateMemberAge(key, inputObj[key])
      return obj
    }, {})
    // check if error object has no strings or values, if there are, then error occured
    const isError = !!Object.keys(errorObj).filter(key => errorObj[key]).length
    return [isError, errorObj]
  }

  handleSubmit = (e) => {
    const {
      coupon,
      utmSource,
      utmCampaign,
      utmMedium,
      childrenInfo,
      selectedMembers,
      memberInfo
    } = this.state

    const selectedChildren = Object.keys(childrenInfo).filter(key => selectedMembers.includes(key))
    const selectedChildrenObject = selectedChildren.reduce((obj, key) => {
      obj[key] = childrenInfo[key]
      return obj
    }, {})

    const selectedMembersKey = Object.keys(memberInfo).filter(key => selectedMembers.includes(key))
    const selectedMembersObject = selectedMembersKey.reduce((obj, key) => {
      obj[key] = memberInfo[key]
      return obj
    }, {})

    const [isError, errors] = this.validateObj({ ...selectedChildrenObject, ...selectedMembersObject })
    this.setState({
      errors
    })
    if (isError) {
      return
    }

    const childrenArray = selectedChildren.map(key => childrenInfo[key])
    // sort DOB's, from eldest to youngest
    const sortedChildrenArray = childrenArray.sort((a, b) => a.diff(b))

    // List of moment DOB's need to be mapped to insured dict [Moment, Moment]
    // {
    //   "1": "YYYY-MM-DD"
    // }
    const childObject = sortedChildrenArray.reduce((obj, dob, idx) => {
      // + 3 because child relationship starts on 3
      obj[idx + 3] = dob.format('YYYY-MM-DD')
      return obj
    }, {})

    let memberObj = {}
    memberObj['1'] = selectedMembersObject['self'].format('YYYY-MM-DD')
    if (selectedMembersObject['spouse']) {
      memberObj['2'] = selectedMembersObject['spouse'].format('YYYY-MM-DD')
    }

    Object.assign(memberObj, childObject)
    const queryString = querySearchBuilder({
      utm_source: utmSource,
      utm_campaign: utmCampaign,
      utm_medium: utmMedium,
      coupon,
      members: encodeURIComponent(JSON.stringify(memberObj))
    })

    this.props.history.push({ pathname: '/cthealth/packages', search: queryString })
  }

  handleAddChild = (e) => {
    let newMemberKey = 'child'
    const { childrenInfo, selectedMembers } = this.state
    const children = Object.keys(childrenInfo).filter(memberKey => memberKey.startsWith('child_')).map(memberKey => memberKey.match(/child_([1-4])/)[1])
    const childIndex = parseInt(children[children.length - 1]) + 1
    newMemberKey = `child_${childIndex}`

    this.setState({
      childrenInfo: {
        ...childrenInfo,
        [newMemberKey]: null
      },
      maxChildren: Object.keys(childrenInfo).length > 1,
      selectedMembers: [...selectedMembers, newMemberKey]
    }, () => {
      window.dataLayer.push({ event: `ciputra-hcp-add-child-${childIndex}` })
    })
  }

  handleToggle = (memberKey, checked) => {
    if (memberKey === 'self') return

    const { selectedMembers } = this.state
    let newSelectedMembers = selectedMembers
    if (checked) {
      newSelectedMembers.push(memberKey)
    } else {
      newSelectedMembers.splice(selectedMembers.indexOf(memberKey), 1)
    }
    this.setState({
      selectedMembers: newSelectedMembers
    })
  }

  render () {
    const {
      memberInfo,
      // selectedMembers,
      // childrenInfo,
      // maxChildren,
      errors
    } = this.state

    return (
      <CtHealthWrapper>
        <div className='card-design'>
          <div className='card-header'>
            <p className='card-header-text mb-0'>Temukan Premi Anda</p>
          </div>
          <div className='card-body opacity'>
            {/* <div class='card-body-subheader'>Anda dapat memilih hingga 5 (lima) anggota.</div> */}
            <div class='card-body-subheader'>Masukkan Tanggal Lahir Anda</div>
            <div className='member-box'>
              {/* <label className='checkbox-container'>
                <span className='checked-label'>Diri Sendiri</span>
                <input
                  type='checkbox'
                  checked
                  onChange={e => this.handleToggle('self', e.target.checked)}
                />
                <span class='checkmark' />
              </label> */}
              <DatePicker selectedDate={(value) => this.setState({ memberInfo: { ...memberInfo, self: value } })} />
              {errors['self'] && (
                <div className='error-message'>
                  {errors['self']}
                </div>
              )}
            </div>
            {/* <div className='member-box'>
              <label className='checkbox-container'>
                <span className={selectedMembers.includes('spouse') && 'checked-label'}>Pasangan</span>
                <input
                  type='checkbox'
                  id={`ciputra-hcp-checkbox-spouse`}
                  checked={selectedMembers.includes('spouse')}
                  onChange={e => this.handleToggle('spouse', e.target.checked)}
                />
                <span class='checkmark' />
              </label>
              {selectedMembers.includes('spouse') && (
                <DatePicker selectedDate={(value) => this.setState({ memberInfo: { ...memberInfo, spouse: value } })} />
              )}
              {errors['spouse'] && (
                <div className='error-message'>
                  {errors['spouse']}
                </div>
              )}
            </div>
            {Object.keys(childrenInfo).map((key, idx) => {
              return (
                <div className='member-box'>
                  <label className='checkbox-container'>Anak {idx + 1}
                    <input
                      id={`ciputra-hcp-checkbox-child-${idx + 1}`}
                      type='checkbox'
                      checked={selectedMembers.includes(key)}
                      onChange={e => this.handleToggle(key, e.target.checked)}
                    />
                    <span class='checkmark' />
                  </label>
                  {selectedMembers.includes(key) && (
                    <DatePicker selectedDate={(value) => this.setState({ childrenInfo: { ...childrenInfo, [key]: value } })} />
                  )}
                  {errors[key] && (
                    <div className='error-message'>
                      {errors[key]}
                    </div>
                  )}
                </div>
              )
            })}
            {!maxChildren && (
              <React.Fragment>
                {Object.keys(memberInfo).length < 5 && (
                  <a className='add-child' onClick={() => this.handleAddChild('child')}>
                    Tambah Anak
                  </a>
                )}
              </React.Fragment>
            )} */}
            <div className='mt-10'>
              <button id='ciputra-hcp-check-premium' className='check-premium' onClick={() => this.handleSubmit()}>
                Cek Premi
              </button>
            </div>
          </div>
        </div>
      </CtHealthWrapper>
    )
  }
}

CtHealth.propTypes = {
}

CtHealth.defaultProps = {
}

export default connect(
  state => ({
  }),
  {
    showOverlay,
    resetOverlay
  }
)(CtHealth)
