import React, { useState } from 'react'
import AddressSlide from '../AddressSlide'
import Carousel from '../Carousel'
import addressContent from './content'
import { AddressTabWrapper } from './index.style'

const AddressTab = () => {
  const [current, setCurrent] = useState(0)

  return (
    <AddressTabWrapper>
      <ul className='flex-container country-flag-container'>
        {
          addressContent.countries.map((country, index) => (
            <li className='country-icon-li' key={index}>
              <div onClick={() => setCurrent(index)}>
                <img
                  className={index === current ? 'country-icon active' : 'country-icon'}
                  src={country.countryIconImage}
                />
              </div>
            </li>
          ))
        }
      </ul>
      <div>
        <Carousel
          slides={addressContent.countries.map(country => (
            <AddressSlide key={country.name} {...country} />
          ))}
          current={current}
        />
      </div>
    </AddressTabWrapper>
  )
}
export default AddressTab
