import React, { Component } from 'react'
import { Row, Col, Select, Form, Button, Spin, notification } from 'antd'
import { connect } from 'react-redux'
import PropTypes from 'prop-types'
import NumberFormat from 'react-number-format'

import IntlMessages from '../utility/intlMessages'
import CrackScreenCardWrapper, { TitleStyle } from './crackScreenCard.style'
import crackscreenActions from '../../redux/crackscreen/actions'
import appActions from '../../redux/app/actions'
import querySearchBuilder from '../../helpers/querySearchBuilder'

const { getCrackscreenBrandModels, getCrackscreenPremium } = crackscreenActions
const { showOverlay, resetOverlay } = appActions

const FormItem = Form.Item
const Option = Select.Option

class CrackScreenCard extends Component {
  constructor (props) {
    super(props)
    this.state = {
      phoneBrand: undefined,
      phoneModels: [],
      phoneModel: undefined,
      phonePriceRangeId: undefined
    }
  }
  componentDidMount = () => {
    const searchParams = new URLSearchParams(this.props.location.search)
    const utmMedium = searchParams.get('utm_medium')
    const utmSource = searchParams.get('utm_source')
    const utmCampaign = searchParams.get('utm_campaign')

    this.setState({
      utmMedium,
      utmSource,
      utmCampaign
    })

    this.props.getCrackscreenBrandModels()
    this.props.getCrackscreenPremium({
      params: { tagName: 'crack_screen_protection_plus_premium' },
      query: { order_by: 'seq_weight' }
    })
  }

  errorNotification = (message = 'Terjadi kesalahan') => {
    notification.error({
      message
    })
  }

  handlePhoneBrandChange = (key) => {
    const { phoneBrandModels } = this.props
    const phoneBrandMapping = phoneBrandModels.find(({ name }) => name === key)
    if (!phoneBrandMapping || !(phoneBrandMapping instanceof Object)) {
      notification.error({
        message: 'Merek tidak ditemukan'
      })
      return
    }

    const phoneModels = phoneBrandMapping.modelList

    if (!phoneModels || !Array.isArray(phoneModels) || !phoneModels.length) {
      this.errorNotification('Merek ini tidak memiliki daftar model')
    } else {
      this.props.form.resetFields(['phone_model'])
      this.setState({
        phoneBrand: key,
        phoneModels,
        phoneModel: undefined
      })
    }
  }

  handlePhoneModelChange = (key) => {
    const { phoneModels } = this.state
    const { premiumList } = this.props
    const phoneModelDetails = phoneModels.find(({ name }) => name === key)

    if (!phoneModelDetails || !(phoneModelDetails instanceof Object)) {
      this.errorNotification('Detil Model HP tidak ditemukan')
      return
    }
    const phonePrice = phoneModelDetails.price

    if (!phonePrice) {
      this.errorNotification('Harga HP tidak ditemukan')
      return
    }

    const premiumObj = premiumList.find(({ additional_data: { min, max } = {} }) => phonePrice > min && phonePrice < max)
    const { id: phonePriceRangeId } = premiumObj

    this.setState({
      phoneModel: key,
      phonePrice,
      phonePriceRangeId
    })
  }

  handlePhonePriceRangeChange = (key) => {
    this.setState({
      phonePriceRangeId: key
    })
  }

  handleSubmit = (e) => {
    e.preventDefault()
    const {
      phoneBrand,
      phoneModel,
      phonePriceRangeId,
      coupon,
      utmSource,
      utmCampaign,
      utmMedium
    } = this.state
    const queryString = querySearchBuilder({
      utm_source: utmSource,
      utm_campaign: utmCampaign,
      utm_medium: utmMedium,
      phoneBrand,
      phoneModel,
      phonePriceRangeId,
      coupon
    })
    this.props.history.push({ pathname: '/crackscreen/details', search: queryString })
  }

  togglePriceForm = () => {
    this.setState(({ showPriceRangeForm }) => ({
      showPriceRangeForm: !showPriceRangeForm,
      phoneBrand: undefined,
      phoneModel: undefined,
      phonePriceRangeId: undefined
    }), () => {
      if (this.state.showPriceRangeForm) {
        this.props.getCrackscreenPremium({
          params: { tagName: 'crack_screen_protection_plus_premium' },
          query: { order_by: 'seq_weight' }
        })
      }
    })
  }

  renderPhoneBrandModelForm = () => {
    const {
      form,
      phoneBrandModels,
      getPremiumListLoading,
      getPhoneBrandModelsLoading
    } = this.props
    const {
      phoneBrand,
      phoneModel,
      phoneModels
    } = this.state
    const { getFieldDecorator } = form
    const phoneBrandOptions = phoneBrandModels.map(({ name }) => (
      <Option
        key={name}
        value={name}
        className='option-select'
      >
        {name}
      </Option>
    ))

    const phoneModelsOptions = phoneModels.map(({ name, price }) => (
      <Option
        key={name}
        value={name}
        className='option-select'
      >
        {name}
      </Option>
    ))

    return (
      <React.Fragment>
        <Col key='brand' span={24} order={0} md={{ span: 8, order: 0 }} className='pt-16 ph-20 pl-0'>
          <TitleStyle>
            <label>Merek Ponsel</label>
          </TitleStyle>
          <FormItem>
            <Spin spinning={!!getPhoneBrandModelsLoading}>
              <Select
                showSearch
                className='full-width card-select'
                placeholder='Pilih Merek'
                onChange={e => this.handlePhoneBrandChange(e)}
                optionFilterProp='children'
                filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
              >
                {phoneBrandOptions}
              </Select>
            </Spin>
          </FormItem>
        </Col>
        {!!phoneBrand && (
          <Col key='model' span={24} order={1} md={{ span: 8, order: 1 }} className='pt-16 ph-20 pl-0'>
            <React.Fragment>
              <TitleStyle>
                <label>Model Ponsel</label>
              </TitleStyle>
              <FormItem>
                {
                  getFieldDecorator('phone_model', {})(
                    <Spin spinning={!!getPremiumListLoading}>
                      <Select
                        value={phoneModel}
                        disabled={!!getPremiumListLoading}
                        showSearch
                        className='full-width card-select'
                        placeholder='Pilih Model'
                        onChange={e => this.handlePhoneModelChange(e)}
                        optionFilterProp='children'
                        filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                      >
                        {phoneModelsOptions}
                      </Select>
                    </Spin>
                  )
                }
              </FormItem>
            </React.Fragment>
          </Col>
        )}
        {!phoneBrand && (
          <Col span={0} md={{ span: 8, order: 3 }} />
        )}
      </React.Fragment>
    )
  }

  renderPriceRangeForm = () => {
    const {
      premiumList,
      getPremiumListLoading
    } = this.props

    const priceRangeOptions = premiumList.map(({
      id,
      additional_data: {
        min,
        max
      } = {}
    }) => (
      <Option
        key={id}
        value={id}
        className='option-select'
      >
          Rp{' '}
        <NumberFormat
          value={parseInt(min)}
          displayType={'text'}
          thousandSeparator={'.'}
          decimalSeparator={','}
        />
          -
        Rp{' '}
        <NumberFormat
          value={parseInt(max)}
          displayType={'text'}
          thousandSeparator={'.'}
          decimalSeparator={','}
        />
      </Option>
    ))

    return (
      <React.Fragment>
        <Col key='price-range' span={24} order={0} md={{ span: 8, order: 0 }} className='pt-16 ph-20 pl-0'>
          <TitleStyle>
            <label>Harga Gadget</label>
          </TitleStyle>
          <FormItem>
            <Spin spinning={!!getPremiumListLoading}>
              <Select
                disabled={!!getPremiumListLoading}
                showSearch
                className='full-width card-select'
                placeholder='Pilih Harga'
                onChange={e => this.handlePhonePriceRangeChange(e)}
                optionFilterProp='children'
                filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
              >
                {priceRangeOptions}
              </Select>
            </Spin>
          </FormItem>
        </Col>
        <Col span={0} md={{ span: 8, order: 3 }} />
      </React.Fragment>
    )
  }

  render () {
    const {
      phoneModel,
      phonePriceRangeId,
      showPriceRangeForm
    } = this.state

    return (
      <CrackScreenCardWrapper>
        <Form onSubmit={this.handleSubmit} id='myForm'>
          <div className='card-design'>
            <div className='card-header'>
              <p className='card-header-text mb-0'>Pilih Perlindunganmu</p>
            </div>
            <div className='card-body opacity'>
              <Row type='flex'>
                {showPriceRangeForm ? this.renderPriceRangeForm() : this.renderPhoneBrandModelForm()}
                <Col span={24} order={3} md={{ span: 8, order: 2 }} className='pt-16 ph-20 pl-0'>
                  <Button
                    disabled={!((phoneModel && phonePriceRangeId) || (phonePriceRangeId && showPriceRangeForm))}
                    className='button-primary'
                    htmlType='submit'
                    form='myForm'
                  >
                    <IntlMessages id='CEK HARGA' />
                  </Button>
                </Col>
                <Col span={24} order={2} md={{ span: 8, order: 3 }} className='price-range-toggle-container'>
                  <a
                    className='price-range-toggle'
                    onClick={this.togglePriceForm}
                  >
                    {showPriceRangeForm ? 'Saya ingin mengisi rincian perangkat' : 'Saya tidak menemukan ponsel saya'}
                  </a>
                </Col>
              </Row>
            </div>
          </div>
        </Form>
      </CrackScreenCardWrapper>
    )
  }
}

CrackScreenCard.propTypes = {
  phoneBrandModels: PropTypes.array.isRequired,
  premiumList: PropTypes.array.isRequired
}

CrackScreenCard.defaultProps = {
  phoneBrandModels: [],
  premiumList: []
}

const WrappedCrackScreenCard = Form.create()(CrackScreenCard)

export default connect(
  state => ({
    phoneBrandModels: state.Crackscreen.phoneBrandModels,
    premiumList: state.Crackscreen.premiumList,
    getPhoneBrandModelsLoading: state.Loading.GET_CRACKSCREEN_BRAND_MODELS,
    getPhoneBrandModelsError: state.Error.GET_CRACKSCREEN_BRAND_MODELS,
    getPremiumListLoading: state.Loading.GET_CRACKSCREEN_PREMIUM,
    getPremiumListError: state.Error.GET_CRACKSCREEN_PREMIUM
  }),
  {
    getCrackscreenBrandModels,
    getCrackscreenPremium,
    showOverlay,
    resetOverlay
  }
)(WrappedCrackScreenCard)
