import React, { Component } from 'react'
import { connect } from 'react-redux'
import { notification } from 'antd'
import CtHealthWrapper from '../CtHealthCard/index.style'
import moment from 'moment'
import DatePicker from '../../Datepicker'

const MEMBER_CONFIG = {
  self: {
    minYear: 18,
    maxYear: 60
  },
  spouse: {
    minYear: 21,
    maxYear: 60
  },
  child: {
    minYear: 0.5,
    maxYear: 60
  }
}

class StarHealth extends Component {
  constructor (props) {
    super(props)
    this.state = {
      selectedMembers: ['self'],
      memberInfo: {
        self: null,
        spouse: null
      },
      childrenInfo: {
        child_1: null
      },
      errors: {}
    }
  }
  componentDidMount = () => {
    const searchParams = new URLSearchParams(this.props.location.search)
    const utmMedium = searchParams.get('utm_medium')
    const utmSource = searchParams.get('utm_source')
    const utmCampaign = searchParams.get('utm_campaign')

    this.setState({
      utmMedium,
      utmSource,
      utmCampaign
    })
  }

  errorNotification = (message = 'Terjadi kesalahan') => {
    notification.error({
      message
    })
  }

  validateMemberAge (key, value) {
    const requiredAge = MEMBER_CONFIG[key] || MEMBER_CONFIG['child']
    const { minYear, maxYear } = requiredAge

    let errorStr = ''
    if (!value) {
      errorStr = 'Wajib diisi'
    } else {
      const age = moment().diff(value, 'years', true)
      if (age < minYear) {
        errorStr = `Umur kurang dari ${minYear} tahun`
      } else if (age > (moment(moment(maxYear).add(1, 'days')), 'years')) {
        errorStr = `Umur lebih dari ${maxYear} tahun`
      }
    }

    return errorStr
  }

  resetErrors = () => {
    this.setState({ errors: {} })
  }

  validateObj = (inputObj, cb) => {
    // check each object's value
    const errorObj = Object.keys(inputObj).reduce((obj, key) => {
      obj[key] = this.validateMemberAge(key, inputObj[key])
      return obj
    }, {})
    // check if error object has no strings or values, if there are, then error occured
    const isError = !!Object.keys(errorObj).filter(key => errorObj[key]).length
    return [isError, errorObj]
  }

  handleSubmit = (e) => {
    const {
      childrenInfo,
      selectedMembers,
      memberInfo
    } = this.state

    const selectedChildren = Object.keys(childrenInfo).filter(key => selectedMembers.includes(key))
    const selectedChildrenObject = selectedChildren.reduce((obj, key) => {
      obj[key] = childrenInfo[key]
      return obj
    }, {})

    const selectedMembersKey = Object.keys(memberInfo).filter(key => selectedMembers.includes(key))
    const selectedMembersObject = selectedMembersKey.reduce((obj, key) => {
      obj[key] = memberInfo[key]
      return obj
    }, {})

    const [isError, errors] = this.validateObj({ ...selectedChildrenObject, ...selectedMembersObject })
    this.setState({
      errors
    })
    if (isError) {
      return
    }

    const childrenArray = selectedChildren.map(key => childrenInfo[key])
    // sort DOB's, from eldest to youngest
    const sortedChildrenArray = childrenArray.sort((a, b) => a.diff(b))

    // List of moment DOB's need to be mapped to insured dict [Moment, Moment]
    // {
    //   "1": "YYYY-MM-DD"
    // }
    const childObject = sortedChildrenArray.reduce((obj, dob, idx) => {
      // + 3 because child relationship starts on 3
      obj[idx + 3] = dob.format('YYYY-MM-DD')
      return obj
    }, {})

    let memberObj = {}
    memberObj['1'] = selectedMembersObject['self'].format('YYYY-MM-DD')
    if (selectedMembersObject['spouse']) {
      memberObj['2'] = selectedMembersObject['spouse'].format('YYYY-MM-DD')
    }

    Object.assign(memberObj, childObject)
    const dob = this.state.memberInfo.self
    this.props.history.push({ pathname: '/starhealth/details', state: { userDob: dob.format('YYYY-MM-DD') } })
  }

  render () {
    const {
      memberInfo,
      errors
    } = this.state
    return (
      <CtHealthWrapper>
        <div className='card-design'>
          <div className='card-header'>
            <p className='card-header-text mb-0'>Temukan Premi Anda</p>
          </div>
          <div className='card-body opacity'>
            {/* <div class='card-body-subheader'>Anda dapat memilih hingga 5 (lima) anggota.</div> */}
            <div class='card-body-subheader'>Masukkan Tanggal Lahir Anda</div>
            <div className='member-box'>
              <DatePicker selectedDate={(value) => this.setState({ memberInfo: { ...memberInfo, self: value } })} />
              {errors['self'] && (
                <div className='error-message'>
                  {errors['self']}
                </div>
              )}
            </div>
            <div className='mt-10'>
              <button id='ciputra-hcp-check-premium' className='check-premium' onClick={() => this.handleSubmit()}>
                Cek Premi
              </button>
            </div>
          </div>
        </div>
      </CtHealthWrapper>
    )
  }
}

export default connect(
  state => ({
  }), {}
)(StarHealth)
